{
  "title": "CSCI-242 Foundations: From Problem Statement to Algorithmic Design",
  "learningObjectives": [
    "Students will articulate precise problem statements including input/output examples and invariants.",
    "Students will select and justify appropriate data structures (lists, stacks, queues, trees, graphs) for a given computational task.",
    "Students will design and implement a solution using decomposition, abstraction, and testing to meet correctness criteria."
  ],
  "beats": [
    {
      "title": "Defining the Problem Space",
      "claim": "Programming begins with precise problem statements, input and output examples, and algorithms written independently of syntax.",
      "example": "Given a list of integers, output the sum of all positive values.",
      "visualDirection": "Display a text box containing the problem statement and two sample input/output pairs side by side.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Core Data Structures",
      "claim": "Lists represent ordered sequences, stacks use last-in first-out access, queues use first-in first-out access, trees represent hierarchy, and graphs represent connected entities.",
      "example": "A queue is appropriate for processing tasks in the order they arrive, while a stack models undo operations.",
      "visualDirection": "Show a diagram with five labeled boxes (List, Stack, Queue, Tree, Graph) each containing a simple icon representing its structure.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Decomposition and Abstraction",
      "claim": "Functions decompose a solution into named operations with parameters and results, and decomposition and abstraction reduce the number of interacting concerns.",
      "example": "Create a function `sum_positive` that takes a list and returns an integer, isolating the logic from the main program.",
      "visualDirection": "Render a flowchart with a top-level box labeled 'Main' branching to a sub-box labeled 'sum_positive' with arrows indicating data flow.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Control Flow and Recursion",
      "claim": "Control structures select or repeat operations, and recursion solves a problem through smaller instances and requires a base case.",
      "example": "A recursive factorial function computes n! by calling itself with n-1 until the base case n=0 is reached.",
      "visualDirection": "Illustrate a call stack diagram showing nested frames for factorial(3) expanding to factorial(2), factorial(1), and factorial(0).",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "State, Identity, and Namespaces",
      "claim": "Python objects have identity, a type, and a value; names are bound to objects within namespaces and scopes.",
      "example": "Two variables `a` and `b` can both reference the same list object, so modifying `a` also changes `b`.",
      "visualDirection": "Draw a memory map with two name labels pointing to a single box labeled 'list object' and a separate box for a distinct integer.",
      "sourceIds": ["python-language-reference"]
    },
    {
      "title": "Exceptions and Error Handling",
      "claim": "Exceptions interrupt normal control flow until a matching handler processes them or they propagate, and debugging separates syntax, runtime, and logical failures.",
      "example": "Attempting to divide by zero raises a ZeroDivisionError that must be caught to prevent program termination.",
      "visualDirection": "Show a timeline where normal execution is interrupted by a red 'Exception' marker, followed by a handler block.",
      "sourceIds": ["python-language-reference"]
    },
    {
      "title": "Correctness and Testing",
      "claim": "Correctness arguments, tests, tracing, and debugging compare intended behavior with observable results, including boundary and error cases.",
      "example": "Test the sorting function with an empty list, a single element, and a list with duplicate values to verify edge cases.",
      "visualDirection": "Present a table with three rows labeled 'Empty', 'Single', 'Duplicates' and columns for 'Input', 'Expected Output', and 'Actual Output'.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Algorithm Selection Criteria",
      "claim": "Searching and sorting algorithms depend on representation and invariants, and the choice and application of appropriate algorithms and data structures are at the core of the course",
      "example": "Binary search requires a sorted list; using it on an unsorted list violates the invariant and yields incorrect results.",
      "visualDirection": "Display a decision tree: start node 'Is data sorted?' branches to 'Yes → Binary Search' and 'No → Linear Search'.",
      "sourceIds": ["opendsa-programming-foundations", "rit-csci-242"]
    },
    {
      "title": "Design and Implementation Workflow",
      "claim": "Assignments requiring a design and an implementation are an integral part of the course, and programs should be reasoned about through explicit state, control flow, data, contracts",
      "example": "Before coding, write a contract specifying preconditions (e.g., non-empty list) and postconditions (e.g., returned sum equals total of positives).",
      "visualDirection": "Show a three-step process diagram: '1. Problem Statement', '2. Design (contracts, data structures)', '3. Implementation'.",
      "sourceIds": ["rit-csci-242", "python-language-reference"]
    },
    {
      "title": "Practical Analysis Checklist",
      "claim": "Debugging separates syntax, runtime, and logical failures, and correctness arguments must include boundary and error cases.",
      "example": "Checklist items: Verify syntax with a linter, run unit tests on edge cases, trace execution with print statements, and review logical invariants.",
      "visualDirection": "Render a checklist graphic with four tick boxes labeled 'Syntax', 'Edge Cases', 'Trace', 'Invariant Review'.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    }
  ]
}
